const appendToeicTopicWords = (
  topicId: string,
  prefix: string,
  start: number,
  entries: Array<[string, string, string, string, string, string, number]>
) => {
  entries.forEach(([word, pinyin, phonetic, meaning, example, exampleTranslation, level], index) => {
    toeicWords.push({
      id: `${prefix}-${String(start + index).padStart(3, "0")}`,
      word,
      pinyin,
      phonetic,
      meaning,
      example,
      exampleTranslation,
      level,
      topicId,
    });
  });
};

