const appendToeicBasicTopicWords = (
  topicId: string,
  prefix: string,
  start: number,
  topicLabel: string,
  entries: Array<[string, string, string, number]>
) => {
  entries.forEach(([word, pinyin, meaning, level], index) => {
    toeicWords.push({
      id: `${prefix}-${String(start + index).padStart(3, "0")}`,
      word,
      pinyin,
      phonetic: "",
      meaning,
      example: `The team reviewed ${word} during the ${topicLabel} discussion.`,
      exampleTranslation: `팀은 ${topicLabel} 논의 중 ${meaning}에 대해 검토했습니다.`,
      level,
      topicId,
    });
  });
};

